"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "Тебя прислал Идрис? Боги благосклонны к Сахре. Кобры поджидают у каждого водопоя",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "Слышишь треск? Гремучие змеи. Сотни. Караваны больше не решаются выходить",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "На Морозном пике видели йети размером с дом. Принеси их шкуры как доказательство",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "Мамонты взбесились с тех пор, как мороз не отступает. Они топчут наши кладовые",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Где стоит камень тишины, смолкает любая песня. Верни звук на вершину",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "Последний и самый могучий из камней душ. Уничтожь его – и камни перестанут расти",
