"Mit einer kurzen Werbung ({0} s) bekommst du dasselbe noch einmal.": "Посмотри короткую рекламу ({0} с), чтобы получить то же самое ещё раз.",
"✓ Heute mit Werbung verdoppelt.": "✓ Сегодня удвоено с помощью рекламы.",
"Werbung": "Реклама",
"Belohnung in {0} s": "Награда через {0} с",
"Belohnung freigeschaltet": "Награда открыта",
"Werbung abbrechen? Dann gibt es keine Belohnung.": "Прервать рекламу? Тогда награды не будет.",
"Weiter ansehen": "Смотреть дальше",
"Tippe auf ▶, um die Werbung zu starten.": "Нажми ▶, чтобы запустить рекламу.",
"Bis zum Ende ansehen – dann gibt es die Belohnung.": "Досмотри до конца, чтобы получить награду.",
"Seelensteine zerschlagen bringt Bücher, Verstärkungen und mit Glück epische Teile.": "Разбивая камни душ, получаешь книги, усиления и, если повезёт, эпические предметы.",
"Sieben Tage in Folge abholen: Tag {0} bringt die Heldentruhe.": "Забирай семь дней подряд: день {0} приносит Сундук героя.",
"Ab Stufe {0} trägt dich ein Drache über Hindernisse.": "С уровня {0} дракон переносит тебя через препятствия.",
"Gemeinsam jagt es sich leichter: Gruppen teilen die Erfahrung.": "Вместе охотиться легче: группы делят опыт.",
"Im Turm der Verdammten warten ab Stufe {0} die stärksten Gegner.": "С уровня {0} в Башне проклятых ждут сильнейшие враги.",
"Werbung abgebrochen – keine Verdopplung.": "Реклама прервана – без удвоения.",
"Belohnung verdoppelt": "Награда удвоена",
"Hol dir jeden Tag die Tagesbelohnung – mit einer kurzen Werbung doppelt, am siebten Tag in Folge wartet die Heldentruhe": "Забирай ежедневную награду каждый день – вдвойне с короткой рекламой, а на седьмой день подряд тебя ждёт Сундук героя",
