// 15.84: Push-Nachrichten
"Benachrichtigungen": "Уведомления",
"Erinnerungen an die Tagesbelohnung, Doppel-EP-Wochenenden, das Ende der PvP-Saison, Weltbosse und nach ein paar Tagen Pause. Höchstens zwei am Tag, nie nachts und nicht, während du spielst. Geplant wird nur auf diesem Gerät, ohne Server.": "Напоминания о ежедневной награде, выходных двойного опыта, конце PvP-сезона, мировых боссах и после нескольких дней перерыва. Не больше двух в день, никогда ночью и не во время игры. Всё планируется только на этом устройстве, без сервера.",
"Die Windows-App meldet sich, solange sie läuft – auch minimiert.": "Приложение для Windows присылает уведомления, пока оно запущено, — даже в свёрнутом виде.",
"Mitteilungen sind in den Geräte-Einstellungen ausgeschaltet: Einstellungen → Seelenstein → Mitteilungen.": "Уведомления отключены в настройках устройства: Настройки → Seelenstein → Уведомления.",
"Als Nächstes": "Далее",
"Benachrichtigungen einschalten?": "Включить уведомления?",
"Seelenstein kann dich an die Tagesbelohnung, Doppel-EP-Wochenenden und Weltbosse erinnern – höchstens zweimal am Tag und nie nachts. Abschalten kannst du das jederzeit in den Einstellungen unter „Figur und Spiel“.": "Seelenstein может напоминать о ежедневной награде, выходных двойного опыта и мировых боссах — не больше двух раз в день и никогда ночью. Отключить это можно в любой момент в настройках, раздел «Персонаж и игра».",
"Nein, danke": "Нет, спасибо",
"Ja, erinnern": "Да, напоминать",
"Benachrichtigungen sind an": "Уведомления включены",
"Benachrichtigungen sind aus": "Уведомления выключены",
"Deine Tagesbelohnung ist wieder bereit!": "Ежедневная награда снова ждёт тебя!",
"Deine Tagesbelohnung ist wieder bereit – heute wartet die Heldentruhe!": "Ежедневная награда снова ждёт тебя — сегодня это Сундук героя!",
"Deine heutige Tagesbelohnung wartet noch auf dich!": "Сегодняшняя ежедневная награда всё ещё ждёт тебя!",
"Die PvP-Saison endet in drei Tagen": "PvP-сезон закончится через три дня",
